function archiveTeamTotals(t){
  const matches=Array.isArray(t?.matches)?t.matches:[];
  let wins=0,draws=0,losses=0,goals=0,against=0;
  for(const m of matches){
    const own=ownClubInMatch(t,m),opp=oppClubInMatch(t,m);
    const gf=num(own?.goals),ga=num(opp?.goals);
    goals+=gf; against+=ga;
    if(gf>ga)wins+=1; else if(gf<ga)losses+=1; else draws+=1;
  }
  return {matches:matches.length,wins,draws,losses,goals,against,winRate:matches.length?100*wins/matches.length:0,goalsPerMatch:matches.length?goals/matches.length:0,concededPerMatch:matches.length?against/matches.length:0};
}
function teamStatsTable(title,stats,scopeLabel){const diff=num(stats.goals)-num(stats.against);return `<div class="card"><h3>${esc(title)}</h3><div class="muted" style="margin-bottom:7px">${esc(scopeLabel)}</div><div class="table-wrap"><table><thead><tr><th>Dato</th><th>Valore</th></tr></thead><tbody><tr><td>Partite</td><td>${num(stats.matches)}</td></tr><tr><td>Vittorie</td><td>${num(stats.wins)}</td></tr><tr><td>Pareggi</td><td>${num(stats.draws)}</td></tr><tr><td>Sconfitte</td><td>${num(stats.losses)}</td></tr><tr><td>Gol fatti</td><td>${num(stats.goals)}</td></tr><tr><td>Gol subiti</td><td>${num(stats.against)}</td></tr><tr><td>Differenza reti</td><td>${diff>0?'+':''}${diff}</td></tr><tr><td>Win rate</td><td>${num(stats.winRate).toFixed(1)}%</td></tr></tbody></table></div></div>`}
